import{z as B,x as A,o,c as p,q as s,j as n,D as e,d as E,s as l,S as i,b as t}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Bootstrap","description":"","frontmatter":{"title":"Bootstrap","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/bootstrap-econ.md","filePath":"econ/bootstrap-econ.md","lastUpdated":1791413859000}'),d={name:"econ/bootstrap-econ.md"};function h(b,a,m,C,c,D){const r=A("Mermaid");return o(),p("div",null,[a[2]||(a[2]=s('<h1 id="bootstrap" tabindex="-1">Bootstrap <a class="header-anchor" href="#bootstrap" aria-label="Permalink to &quot;Bootstrap&quot;">​</a></h1><div class="epigraph"><p>用样本的经验分布去模拟 $\\hat\\theta$ 再抽一次会落在哪；它给出非线性统计量与少簇推断的可行近似，不是第二套数据，更不是把偏误洗掉。</p><footer>—— Efron, Bootstrap Methods: Another Look at the Jackknife, Annals of Statistics 1979；Cameron, Gelbach and Miller 的 wild cluster bootstrap；对照 Angrist and Pischke</footer></div><p><a href="/econ/heterogeneous-effects">上一课</a>声明：OLS、IV、DiD 在 \\(\\tau_i\\) 异质时估的是不同加权平均，IV 对准编译器 LATE 而不是 ATE。本课不重写单调性与 MTE。缺口是精度：这些加权平均的抽样分布，在 \\(n\\) 小、簇少、统计量非光滑时，不必接近正态。解析三明治可以不存在或名义水平很差。Bootstrap 用重抽样逼近 \\(\\hat\\theta\\) 的分布。后课<a href="/econ/multiple-testing-econ">多重检验</a>管许多假设同时测；本课管<strong>单个</strong>（或少数几个）参数的推断引擎。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>渐近口号是 \\(\\sqrt{n}(\\hat\\theta-\\theta)\\Rightarrow N(0,V)\\)，于是 \\(t\\) 与 CI。异质加权、中位数、GMM 的 \\(J\\)、少簇的 DiD，都可以让这句话在有限样本里很差。<a href="/econ/clustered-se">聚类标准误</a>已经警告 \\(G\\) 小时 CRVE 偏乐观。缺口是：若不相信正态，用样本自己当总体的插件估计，重复「再抽一次同样大小的样本」。Efron 的非参数 bootstrap：从 \\(F_n\\) 有放回抽 \\(n\\) 次，得 \\(\\hat\\theta^{(b)}\\)，\\(b=1,\\ldots,B\\)，用经验分位数建区间。</p><p>关键限制：数据生成过程里的依赖，必须写进重抽方案。i.i.d. 行可以抽行；聚类数据抽行等于拆掉簇——名义水平可以比不用 bootstrap 更坏。</p><h3 id="重抽样不是第二套识别" tabindex="-1">重抽样不是第二套识别 <a class="header-anchor" href="#重抽样不是第二套识别" aria-label="Permalink to &quot;重抽样不是第二套识别&quot;">​</a></h3><p>Bootstrap 的随机性来自你已经观察到的样本，不是新的实验。\\(\\mathbb{E}[u\\mid X]\\neq 0\\) 时，每一次 \\(\\hat\\theta^{(b)}\\) 都在同一个偏误周围抖动，区间可以很窄地盖住错误的目标。它修的是「给定估计量，不确定性有多大」，不修「估计量对准谁」。与上一课分工：先声明 LATE 还是 ATT，再谈这个数的抽样分布。</p><p><span class="marginnote">匹配课已警告：离散最近邻上朴素 bootstrap 可以不一致。Abadie–Imbens 要渐近修正。装置与数据的依赖结构必须匹配，不能「一律 boot, reps(500)」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>常用三种。(1) Pairs：成对抽 \\((y_i,x_i)\\)，对异方差自然。(2) 残差 / wild：保留 \\(X\\)，用 Rademacher 权重乘 \\(\\hat u\\)（或整簇 \\(\\hat u_g\\)），适合回归与少簇。(3) 块 bootstrap：时间序列按块抽，块长敏感。聚类：以 \\(G\\) 个簇为单位有放回抽 \\(G\\) 次，每次带走该簇全部行。百分位区间取 \\(\\{\\hat\\theta^{(b)}\\}\\) 的 \\(\\alpha/2\\) 与 \\(1-\\alpha/2\\) 分位；BCa 再修偏误与偏度。</p><p>与三明治并列报告是应用惯例：两者接近，心里踏实；差很远，先查依赖结构与弱识别，而不是只改 \\(B\\)。</p>',12)),(o(),n(i,null,{default:e(()=>[l(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20HET%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%3A%20%E5%8A%A0%E6%9D%83%E5%B9%B3%E5%9D%87%E6%98%AF%E8%B0%81%22%5D%20--%3E%20DIST%5B%22%E6%9C%AC%E8%AF%BE%3A%20%E8%BF%99%E4%B8%AA%E5%B9%B3%E5%9D%87%E7%9A%84%E6%8A%BD%E6%A0%B7%E5%88%86%E5%B8%83%22%5D%0A%20%20DIST%20--%3E%20IID%5B%22i.i.d.%20%E6%8A%BD%E8%A1%8C%22%5D%0A%20%20DIST%20--%3E%20CL%5B%22%E6%8C%89%E7%B0%87%20%2F%20wild%20%E9%87%8D%E6%8A%BD%22%5D%0A%20%20CL%20--%3E%20CI%5B%22%E5%88%86%E4%BD%8D%E6%95%B0%E5%8C%BA%E9%97%B4%E6%88%96%20SE%22%5D%0A%20%20CI%20--%3E%20MT%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E8%AE%B8%E5%A4%9A%E5%81%87%E8%AE%BE%E5%90%8C%E6%97%B6%E6%B5%8B%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"\\(B\\) 太小，分位数本身很吵；推断要稳，\\(B\\) 常用几百到几千。计算成本不是把识别外包给计算机。",-1)),a[4]||(a[4]=t("p",null,[t("span",{class:"marginnote"},"数字实例：\\(B=1000\\) 时，把 1000 个重抽估计从小到大排队，第 25 个和第 975 个就是 95% 区间的两个端点。\\(B=50\\) 时「第 1.25 个观测」这种分位数根本没法定义，这就是 \\(B\\) 太小区间不稳的直观来源。")],-1)),a[5]||(a[5]=t("p",null,[t("span",{class:"marginnote"},"术语翻译：wild bootstrap 的 Rademacher 权重就是抛硬币——每个残差（或整簇残差）随机乘 \\(+1\\) 或 \\(-1\\)。它不重排数据，只翻转扰动的方向，因此簇内的相关形状原封不动，这正是它适合少簇场合的原因。")],-1)),a[6]||(a[6]=t("h2",{id:"机制",tabindex:"-1"},[E("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[7]||(a[7]=t("p",null,"插件逻辑：\\(F_n\\) 是 \\(F\\) 的估计，在 \\(F_n\\) 上重复估计量的映射，逼近该映射在 \\(F\\) 上的抽样分布。对光滑 M-估计，bootstrap SE 与三明治渐近等价，本课的增量主要在非光滑与少簇。Wild cluster 保留簇内相关形状，只随机翻转符号，因此在 \\(G\\) 很小时 size 往往优于「簇得分当正态」。弱工具时，bootstrap 可以复制有限样本偏误——区间会围绕偏的中心，这是诚实的，不是 bug；它提醒你点估计本身不可信。",-1)),(o(),n(i,null,{default:e(()=>[l(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E6%9C%AA%E7%9F%A5%E6%80%BB%E4%BD%93%20F%22%5D%20--%3E%7C%22%E7%9C%9F%E5%AE%9E%E4%B8%96%E7%95%8C%E6%8A%BD%E4%BA%86%E4%B8%80%E6%AC%A1%22%7C%20S%5B%22%E6%89%8B%E4%B8%8A%E7%9A%84%E6%A0%B7%E6%9C%AC%2C%20n%20%E4%B8%AA%E8%A7%82%E6%B5%8B%22%5D%0A%20%20S%20--%3E%7C%22%E7%BB%8F%E9%AA%8C%E5%88%86%E5%B8%83%20Fn%20%E5%BD%93%E6%9B%BF%E8%BA%AB%22%7C%20PLUG%5B%22%E5%9C%A8%20Fn%20%E4%B8%8A%E6%8A%8A%E4%BC%B0%E8%AE%A1%E9%87%8F%E9%87%8D%E8%B7%91%20B%20%E9%81%8D%22%5D%0A%20%20PLUG%20--%3E%7C%22%E7%AC%AC%20b%20%E9%81%8D%E5%BE%97%E4%B8%80%E4%B8%AA%E4%BC%B0%E8%AE%A1%22%7C%20TH%5B%22B%20%E4%B8%AA%E4%BC%B0%E8%AE%A1%E6%8E%92%E6%88%90%E4%B8%80%E5%88%97%22%5D%0A%20%20TH%20--%3E%7C%22%E5%8F%96%202.5%25%20%E4%B8%8E%2097.5%25%20%E4%BD%8D%E7%BD%AE%22%7C%20CI%5B%2295%25%20%E7%BD%AE%E4%BF%A1%E5%8C%BA%E9%97%B4%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=s('<p>这张图回答的是：重抽为什么能「无中生有」出抽样分布。它并没有造新数据，只是把「从总体抽一次样本」这个动作，在经验分布 \\(F_n\\) 这个微缩沙盘上重新演了 \\(B\\) 遍；近似质量取决于 \\(F_n\\) 像不像 \\(F\\)，这正是依赖结构必须写进重抽方案的原因。</p><p><span class="marginnote">Cameron–Gelbach–Miller（2008）把 wild cluster 接到少簇推断。它与本课是同一装置：重抽必须尊重「独立单位是簇」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>强依赖、单位根、参数在边界（如方差为零）时，朴素 bootstrap 可以不一致，要子抽样或改统计量。本课不推一致性的全部技术条件。多重假设时，对每个系数单独 bootstrap 不控制族错误率——下一课 Holm 与 BH。量化栏对收益率序列另有块长惯例，本课不搬，以免进交易执行。</p><p><span class="marginnote">常见误区：初学者容易以为「跑够了次数，bootstrap 就把偏误洗掉了」。实际上每一次重抽都在同一个偏误周围抖动，\\(B\\) 再大，区间也只是窄窄地罩住那个错的目标。它修的是不确定性有多大，不是对准了谁。</span></p><p>后课默认：异质加权平均的推断，截面可 pairs，聚类用 cluster 或 wild，并与稳健 SE 对照。不要用 bootstrap 替代排除约束或平行趋势。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Bootstrap 用 \\(F_n\\) 模拟 \\(\\hat\\theta\\) 的抽样分布，不提供新实验。</li><li>依赖结构必须写进方案：簇抽簇，序列抽块。</li><li>少簇时 wild cluster 常优于正态 CRVE。</li><li>它不修正外生失败，只修正有限样本覆盖。</li><li>多假设的错误率留给下一课。</li><li>出处：Efron, <em>Annals of Statistics</em> 1979；Cameron, Gelbach and Miller, <em>ReStat</em> 2008；Cameron and Trivedi；Angrist and Pischke。</li></ul>',8))])}const T=B(d,[["render",h]]);export{f as __pageData,T as default};
